const app=document.querySelector('#app'), detail=document.querySelector('#detail'), notice=document.querySelector('#notice');
const T={ftir:'FTIR',h1:'¹H NMR',c13:'¹³C NMR',uv:'UV–Vis',xrd:'XRD',fluorescence:'Fluorescence',raman:'Raman'};
const referenceTechniques=['ftir','h1','c13','uv'];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=v=>{try{let u=new URL(v);return u.protocol==='https:'?esc(u.href):'#'}catch{return '#'}};
let statsData,rdkitPromise,routeRun=0,offset=0,query='',collection='',uploadCompound=null;
function flash(message,error=false){notice.textContent=message;notice.className=error?'error':'';notice.style.display='block';clearTimeout(flash.timer);flash.timer=setTimeout(()=>notice.style.display='none',8000)}
async function api(url,data){const r=await fetch(url,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-SpectraTrace':'1'},body:JSON.stringify(data)});const result=await r.json();if(!r.ok)throw Error(result.error||'Request failed');return result}
function coverage(types=[]){return `<div class="coverage">${Object.entries(T).map(([id,label])=>`<span class="badge ${types.includes(id)?'available':''}">${label} ${types.includes(id)?'reviewed':'missing'}</span>`).join('')}</div>`}
function collectionCoverage(c){return `<div class="coverage">${Object.entries(T).map(([id,label])=>{const n=c.techniqueCoverage?.find(z=>z.technique===id)?.n||0;return `<span class="badge ${n?'available':''}">${label} ${n} / ${c.identities}</span>`}).join('')}</div>`}
document.querySelector('#detail .close').onclick=()=>detail.close();detail.addEventListener('click',e=>{if(e.target===detail)detail.close()});
async function render(){const run=++routeRun,hash=location.hash.slice(1)||'home';window.focusPortal.closeAll();document.body.classList.toggle('landing',hash==='home');document.body.classList.toggle('focus-portal',/^(find|compound|unknown|candidate)\//.test(hash));document.body.classList.toggle('upload-focus',hash==='upload-unknown');document.body.dataset.page=hash.split('/')[0];app.classList.remove('upload-shell');document.querySelector('.nav-more').open=false;try{
  if(hash==='home'){home();return}if(/^(find|compound|unknown|candidate)\//.test(hash)){await window.focusPortal.route(hash,{api,structure,esc,app});return}if(hash==='upload-unknown'){window.studentWorkflow.upload({api,structure,esc,app});window.scrollTo(0,0);return}app.innerHTML='<p class="loading">Loading…</p>';statsData=await api('/api/stats');if(run!==routeRun)return;

  if(hash==='home')home();else if(hash==='library')await library();else if(hash==='logic')await logicPage();else if(hash==='evidence')await evidenceLibrary();else if(hash.startsWith('evidence/'))await evidenceView(hash.slice(9));else if(hash.startsWith('upload-'))upload(hash==='upload-reference'?'reference':'unknown');else if(hash==='samples')await samples();else if(hash.startsWith('sample/'))await sampleView(hash.slice(7));else if(hash==='settings')await settings();else location.hash='home';
  document.querySelectorAll('nav a').forEach(a=>a.setAttribute('aria-current',a.hash===location.hash?'page':'false'));if(run!==routeRun)return;compactPage(hash);window.scrollTo(0,0);
}catch(e){app.innerHTML=`<div class="empty"><h1>Data bank unavailable</h1><p>${esc(e.message)}</p><p>Keep the local server running. Your saved files are not stored in this browser.</p><button id="retry">Retry</button></div>`;document.querySelector('#retry').onclick=render}}
function home(){app.innerHTML=`<section class="hero"><h1>Spectra<span>Trace</span></h1><form id="home-search" class="home-search" role="search"><svg class="search-icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.3"/><path d="m16 16 4.3 4.3"/></svg><input id="home-q" aria-label="Search compounds" placeholder="Search compounds" autocomplete="off"><button type="submit" aria-label="Search"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-5-5 5 5-5 5"/></svg></button></form><a class="button primary home-upload" href="#upload-unknown"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 16V4m-4 4 4-4 4 4M5 15v5h14v-5"/></svg>Upload file</a></section>`;
  document.querySelector('#home-search').onsubmit=e=>{e.preventDefault();query=document.querySelector('#home-q').value;collection='';offset=0;location.hash='find/'+encodeURIComponent(query.trim())};


}
function library(){app.innerHTML=`<div class="section-head"><div><span class="eyebrow">Compound library</span><h1>Data bank</h1></div><a class="button primary" href="#upload-reference">Add reference</a></div><form id="filters" class="toolbar"><input id="q" aria-label="Search data bank" placeholder="Name, formula or InChIKey" value="${esc(query)}"><select id="collection" aria-label="Collection"><option value="">All collections</option>${statsData.collections.map(c=>`<option value="${c.id}" ${c.id===collection?'selected':''}>${esc(c.name)} (${c.identities})</option>`).join('')}</select><button>Search</button></form><p class="muted small">Badges show reviewed spectra only. <a href="#logic">Structure guides</a> are separate.</p><div id="library-results"></div>`;document.querySelector('#filters').onsubmit=e=>{e.preventDefault();query=document.querySelector('#q').value;collection=document.querySelector('#collection').value;offset=0;return loadLibrary()};document.querySelector('#collection').onchange=()=>document.querySelector('#filters').requestSubmit();loadLibrary()}
async function loadLibrary(){const holder=document.querySelector('#library-results');try{const data=await api(`/api/compounds?q=${encodeURIComponent(query)}&collection=${encodeURIComponent(collection)}&offset=${offset}`);if(!holder.isConnected)return;holder.innerHTML=`<p class="muted small">${data.total.toLocaleString()} matching identities</p>${data.rows.length?`<div class="table-wrap"><table><thead><tr><th>Compound</th><th>Formula / mass</th><th>Experimental reference coverage</th></tr></thead><tbody>${data.rows.map(c=>`<tr><td><button class="link" data-compound="${c.id}">${esc(c.name)}</button><small class="hash">${esc(c.inchikey)}</small></td><td>${esc(c.formula)}<small>${esc(c.mass)} g/mol</small></td><td>${coverage(c.available?.split(',')||[])}</td></tr>`).join('')}</tbody></table></div><div class="pager"><button id="prev" ${offset===0?'disabled':''}>Previous</button><span class="small muted">${offset+1}–${offset+data.rows.length} of ${data.total}</span><button id="next" ${offset+30>=data.total?'disabled':''}>Next</button></div>`:'<div class="empty">No identities match this search. Try another name, formula or collection.</div>'}`;
    holder.querySelectorAll('[data-compound]').forEach(b=>b.onclick=()=>showCompound(b.dataset.compound));if(data.rows.length){holder.querySelector('#prev').onclick=()=>{offset=Math.max(0,offset-30);loadLibrary()};holder.querySelector('#next').onclick=()=>{offset+=30;loadLibrary()}}}catch(e){holder.textContent=e.message}}
async function structure(smiles,target){try{rdkitPromise ||= initRDKitModule({locateFile:f=>'/vendor/'+f});const rdkit=await rdkitPromise;if(!target.isConnected)return;const m=rdkit.get_mol(smiles);if(!m)throw Error('Structure could not be drawn');target.innerHTML=m.get_svg(420,260);m.delete()}catch(e){target.textContent='Structure drawing unavailable. The source SMILES and original identity link remain available.'}}
async function showCompound(id){try{const c=await api('/api/compounds/'+id);document.querySelector('#detail-body').innerHTML=`<span class="eyebrow">Source-linked identity</span><h1>${esc(c.name)}</h1><div class="split"><div class="structure" id="mol">Drawing molecular structure…</div><div><dl class="metadata"><dt>Formula</dt><dd>${esc(c.formula)}</dd><dt>Molar mass</dt><dd>${esc(c.mass)} g/mol</dd><dt>InChIKey</dt><dd><code>${esc(c.inchikey)}</code></dd><dt>SMILES</dt><dd><code>${esc(c.smiles)}</code></dd></dl>${coverage(c.coverage.map(s=>s.technique))}<p class="small muted">Badges show reviewed uploads only. Imported source evidence is listed separately below.</p></div></div><h2 style="margin-top:1.5rem">Identity provenance</h2>${c.sources.map(({provenance:p})=>`<section class="sample"><h3>${esc(p.provider)} · ${esc(p.sourceId)}</h3><p class="small muted">${esc(p.family)}<br>Retrieved ${esc(p.fetchedAt?.slice(0,10))} · ${esc(p.license)}</p><a href="${safeUrl(p.sourceUrl)}" target="_blank" rel="noopener noreferrer">Open original compound record</a>${p.doi?`<p class="small"><a href="${safeUrl('https://doi.org/'+p.doi)}" target="_blank" rel="noopener noreferrer">${esc(p.publication||p.doi)}</a> · Identity literature; spectral raw data not imported.</p>`:''}</section>`).join('')}<h2 style="margin-top:1.5rem">Experimental submissions</h2>${c.samples.length?c.samples.map(s=>`<p><a class="sample-link" href="#sample/${s.id}">${esc(s.label)}</a> <span class="badge ${s.status==='approved'?'available':'pending'}">${s.status==='approved'?'reviewed':'pending review'}</span></p>`).join(''):'<p class="muted">No experimental files submitted for this identity.</p>'}<button id="contribute" class="primary">Add measured spectra for this compound</button>`;document.querySelector('#contribute').insertAdjacentHTML('beforebegin',`<h2 style="margin-top:1.5rem">Imported external evidence</h2><p class="small muted">Separate experiments linked by exact identity, not one combined sample. These imports await independent review.</p>${c.external?.length?c.external.map(z=>`<p><a class="sample-link" href="#evidence/${z.id}">${T[z.technique]} · ${esc(representations[z.representation])} · ${esc(z.source_id)}</a> <span class="badge pending">${esc(z.status)}</span></p>`).join(''):'<p class="muted">No imported spectral evidence for this exact identity.</p>'}`);if(c.logic)document.querySelector('#contribute').insertAdjacentHTML('beforebegin',logicPanel(c.logic));compactCompound();detail.showModal();structure(c.smiles,document.querySelector('#mol'));document.querySelector('#contribute').onclick=()=>{uploadCompound=c;detail.close();if(location.hash==='#upload-reference')upload('reference');else location.hash='upload-reference'};document.querySelectorAll('.sample-link').forEach(a=>a.onclick=()=>detail.close())}catch(e){flash(e.message,true)}}
function textField(name,label,placeholder='',required=false,type='text'){return `<label>${label}<input name="${name}" type="${type}" placeholder="${esc(placeholder)}" ${required?'required':''}></label>`}
function filePanel(t){return `<section class="file-card" data-technique="${t}"><h3>${T[t]}</h3><label>Original file · maximum 25 MB<input type="file" name="file-${t}"></label><details><summary>Acquisition details & parsing settings</summary><p class="small muted">Two-column CSV/TXT only for numerical comparison. Other formats are archived without interpretation. Use decimal points; no thousands separators.</p><div class="fields"><label>x units<select name="${t}-xUnit"><option value="${t==='ftir'?'cm-1':t==='uv'?'nm':'ppm'}">${t==='ftir'?'Wavenumber (cm⁻¹)':t==='uv'?'Wavelength (nm)':'Chemical shift (ppm)'}</option></select></label><label>Data format<select name="${t}-format"><option value="continuous">Continuous trace</option>${['h1','c13'].includes(t)?'<option value="peaks">Peak list (ppm, intensity)</option>':''}</select></label><label>y convention<select name="${t}-yMode">${t==='ftir'?'<option value="absorbance">Absorbance</option><option value="transmittance-percent">Transmittance (%)</option>':t==='uv'?'<option value="absorbance">Absorbance</option>':'<option value="intensity">Intensity</option>'}</select></label>${textField(t+'-instrument','Instrument / model','e.g. instrument model')}${textField(t+'-date','Acquisition date','',false,'date')}${t==='ftir'?`<label>Phase<select name="ftir-phase"><option value="">Select phase</option><option>solid</option><option>liquid</option><option>solution</option><option>gas</option></select></label><label>Measurement mode<select name="ftir-measurement"><option value="">Select mode</option><option>ATR</option><option>KBr transmission</option><option>liquid transmission</option><option>gas transmission</option></select></label>${textField('ftir-resolution','Resolution (cm⁻¹)','e.g. 4')}`:`${textField(t+'-solvent','Solvent','e.g. CDCl3, DMSO-d6, methanol')}${['h1','c13'].includes(t)?textField(t+'-frequency','Observed nucleus frequency (MHz)','e.g. 400 for ¹H; 100 for ¹³C'):`${textField('uv-concentration','Concentration + unit','e.g. 10 µM')}${textField('uv-pathLength','Path length + unit','e.g. 1 cm')}`}`}${textField(t+'-notes','Processing / reference notes','e.g. baseline corrected; TMS referenced')}</div></details></section>`}
function upload(kind){const ref=kind==='reference',requestId=crypto.randomUUID();app.innerHTML=`<span class="eyebrow">${ref?'Contribute experimental evidence':'Keep the identity unknown'}</span><h1>${ref?'Add reference':'Upload spectra'}</h1><p class="muted">${ref?'Link measured files to a known identity. A separate review is required before they enter matching.':'Add files from the same sample. Its identity stays unknown.'}</p><form id="upload-form"><div class="split"><section class="panel"><h2>Sample</h2><div class="fields">${textField('label','Sample name','e.g. batch-2026-014',true)}${textField('contributor','Researcher / laboratory','Researcher and lab',ref)}${ref?`<div class="span"><label>Known catalog compound<input id="compound-search" placeholder="Search and select the independently identified compound" autocomplete="off"></label><div id="picker-results"></div><p id="selected-compound" class="readonly" ${uploadCompound?'':'hidden'}>${uploadCompound?esc(uploadCompound.name)+' · '+esc(uploadCompound.inchikey):''}</p><p class="small muted">Selecting an identity is a reference assertion, not an identification result.</p></div>`:''}<label class="span">Origin / publication / experimental source<textarea name="provenance" placeholder="Your experiment, publication DOI, or dataset accession" ${ref?'required':''}></textarea></label><label class="span">Reuse permission / license<select name="license" ${ref?'required':''}><option value="">Select permission</option><option>Private research use only; not authorized for public redistribution</option><option>CC BY 4.0</option><option>CC BY-SA 4.0</option><option>CC BY-NC 4.0</option><option>CC0 1.0</option><option>Permission documented in provenance</option></select></label>${textField('purity','Purity / mixture notes','e.g. HPLC 98%, method and caveats')}${textField('batch','Batch / lot','Optional batch ID')}<label class="span">Sample preparation / notes<textarea name="notes" placeholder="Preparation, concentration, temperature or other conditions"></textarea></label></div></section><aside class="panel"><h2>File handling & limitations</h2><p class="small muted">Original bytes are retained with a SHA-256 fingerprint. Parseable values are stored separately for plotting and comparison.</p><p class="small muted">${ref?'Include the instrument and acquisition date for each file. FTIR also needs phase, measurement mode and resolution; NMR needs solvent and frequency; UV–Vis needs solvent, concentration and path length.':'An unknown sample never becomes a reference automatically. Leave the identity unset. Include phase/mode for FTIR or solvent for NMR/UV to enable compatible comparisons.'}</p><div class="banner warning">Not a validated identification method. FTIR alone may suggest similar references but cannot establish a unique structure. No match is reported when the bank has no eligible spectra.</div><p class="small muted">Native/binary files and JCAMP-DX are archived only in this first version. Export two-column CSV/TXT from your instrument software for matching.</p></aside></div><div class="spectra-grid">${referenceTechniques.map(filePanel).join('')}</div><div class="section-head"><p class="small muted">Files from this form are linked to one sample. Upload a separate sample if they are from different material.</p><button id="save" class="primary">${ref?'Save for review':'Save & compare unknown'}</button></div><p id="upload-error" role="alert" class="small" style="color:var(--warn)"></p></form>`;
  const form=document.querySelector('#upload-form');let chosen=ref?uploadCompound:null;uploadCompound=null;
  if(ref){let timer,searchRun=0;document.querySelector('#compound-search').oninput=e=>{clearTimeout(timer);const search=e.target.value,current=++searchRun;timer=setTimeout(async()=>{try{const d=await api('/api/compounds?q='+encodeURIComponent(search));if(current!==searchRun||!form.isConnected)return;const holder=document.querySelector('#picker-results');holder.innerHTML=d.rows.slice(0,8).map(c=>`<button type="button" data-select="${c.id}">${esc(c.name)} · ${esc(c.formula)}</button>`).join('');holder.querySelectorAll('button').forEach(b=>b.onclick=()=>{chosen=d.rows.find(c=>String(c.id)===b.dataset.select);holder.innerHTML='';const selected=document.querySelector('#selected-compound');selected.hidden=false;selected.textContent=chosen.name+' · '+chosen.inchikey;document.querySelector('#compound-search').value=''})}catch(e){flash(e.message,true)}},250)};}
  form.onsubmit=async e=>{e.preventDefault();const save=document.querySelector('#save'),error=document.querySelector('#upload-error');error.textContent='';save.disabled=true;try{
    if(ref&&!chosen)throw Error('Search and select the known catalog identity first.');if(!ref)window.focusPortal.startUpload();
    const fd=new FormData(form),files=[];
    for(const t of referenceTechniques){const f=form.elements['file-'+t].files[0];if(!f)continue;if(f.size>25000000)throw Error(T[t]+': file exceeds 25 MB.');const meta={};for(const [k,v] of fd)if(k.startsWith(t+'-'))meta[k.slice(t.length+1)]=v;
      if(ref){const needed=['instrument','date',...(t==='ftir'?['phase','measurement','resolution']:['h1','c13'].includes(t)?['solvent','frequency']:['solvent','concentration','pathLength'])];for(const key of needed)if(!meta[key]?.trim())throw Error(T[t]+': fill in '+key+' under Acquisition details.');}
      const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('Could not read '+f.name));reader.readAsDataURL(f)});
      files.push({name:f.name,technique:t,metadata:meta,base64});if(!ref)window.focusPortal.updateUpload(20+files.length*12);
    }
    if(!files.length)throw Error('Select at least one spectrum file.');
    const metadata={};for(const k of ['contributor','provenance','license','purity','batch','notes'])metadata[k]=fd.get(k)||'';
    const saved=await api('/api/samples',{id:requestId,kind,label:fd.get('label'),compoundId:chosen?.id,metadata,files});if(ref)flash('Original files and sample record saved.');location.hash=(ref?'sample/':'unknown/')+saved.id;
  }catch(e){window.focusPortal.stopUpload();error.textContent=e.message;save.disabled=false;}}
}
async function samples(){const rows=await api('/api/samples');if(location.hash!=='#samples')return;app.innerHTML=`<div class="section-head"><div><span class="eyebrow">One sample, linked evidence</span><h1>Samples & review</h1></div><div class="actions"><a class="button" href="#upload-unknown">Add unknown</a><a class="button primary" href="#upload-reference">Add reference</a></div></div><p class="muted small">Only approved, parseable reference spectra participate in comparisons. Reviewer decisions are recorded locally; this version has no independent reviewer accounts.</p>${rows.length?rows.map(s=>`<section class="sample"><div class="sample-head"><div><span class="badge ${s.status==='approved'?'available':s.status==='pending'?'pending':''}">${s.status==='approved'?'reviewed reference':s.status==='pending'?'pending review':'unknown sample'}</span><h2>${esc(s.label)}</h2><p class="muted small">${esc(s.compound_name||'Identity not assigned')} · ${esc(s.created_at.slice(0,10))}<br>${esc(s.metadata.contributor)}</p></div><a class="button" href="#sample/${s.id}">${s.status==='pending'?'Open & review':'Open sample'}</a></div></section>`).join(''):'<div class="empty"><h2>No experimental samples yet</h2><p>The catalog is populated with identities, but not spectra. Add your first independently identified reference to begin building the measured library.</p><a class="button primary" href="#upload-reference">Add first reference</a></div>'}`}
function plot(parsed,t,metadata){
  const labels={ftir:'Wavenumber (cm⁻¹)',h1:'Chemical shift (ppm)',c13:'Chemical shift (ppm)',uv:'Wavelength (nm)',xrd:'2θ (°)',fluorescence:'Emission wavelength (nm)',raman:'Raman shift (cm⁻¹)'};
  const yLabels={'transmittance-percent':'Transmittance (%)',absorbance:'Absorbance (a.u.)',intensity:'Intensity (a.u.)',reflectance:'Reflectance (source units)'};
  const chart=window.focusSpectraData.chart({points:parsed.points,technique:t,kind:metadata.format==='peaks'?'peaks':'curve',yUnit:yLabels[metadata.yMode]||metadata.yMode||'Intensity (source units)'});
  const number=v=>Number(v.toPrecision(4)).toString();
  return `<svg class="plot" viewBox="0 0 800 365" role="img" aria-label="${T[t]} source data plot"><path d="M68 65V300H732" fill="none" stroke="#b4c7bc"/><path d="${chart.path}" fill="none" stroke="#246957" stroke-width="1.4"/><g fill="#62766e" font-size="12" font-family="system-ui">${chart.ticks.map(z=>`<text x="${z.x}" y="322" text-anchor="middle">${number(z.value)}</text>`).join('')}${chart.yTicks.map(z=>`<text x="60" y="${z.y+4}" text-anchor="end">${number(z.value)}</text>`).join('')}<text x="400" y="348" text-anchor="middle">${labels[t]}</text><text transform="translate(18 183) rotate(-90)" text-anchor="middle">${esc(yLabels[metadata.yMode]||metadata.yMode||'Intensity (source units)')}</text></g></svg>`;
}
async function sampleView(id){const s=await api('/api/samples/'+id);if(location.hash!=='#sample/'+id)return;app.innerHTML=`<div class="section-head"><div><span class="eyebrow">${s.kind==='unknown'?'Unknown sample':'Named reference submission'}</span><h1>${esc(s.label)}</h1><span class="badge ${s.status==='approved'?'available':'pending'}">${s.status==='approved'?'reviewed':s.status==='pending'?'pending review':'identity unassigned'}</span></div><a class="button ghost" href="#samples">All samples</a></div><div class="split"><section class="panel"><h2>Sample provenance</h2><dl class="metadata">${Object.entries(s.metadata).filter(([,v])=>v).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}<dt>Saved</dt><dd>${esc(s.created_at)}</dd>${s.review?`<dt>Reviewer</dt><dd>${esc(s.review.reviewer)}</dd><dt>Evidence</dt><dd>${esc(s.review.evidence)}</dd><dt>Reviewed</dt><dd>${esc(s.reviewed_at)}</dd>`:''}</dl></section><section class="panel"><h2>${s.kind==='reference'?'Linked compound':'Comparison scope'}</h2>${s.kind==='reference'?`<div id="sample-compound"><p class="muted">Loading identity…</p></div>`:`<p class="small muted">Only approved reference samples are searched. Conditions must agree: phase and measurement mode for FTIR; solvent for NMR/UV. At least 70% of the x-range must overlap.</p><p class="small muted">Ranked first by number of matched techniques, then by equal-weight mean similarity. Missing techniques are not scored.</p><button id="compare" class="primary">Compare reviewed references</button>`}</section></div><div class="spectra-grid" style="margin-top:1.2rem">${s.spectra.map(z=>`<section class="panel"><div class="section-head" style="margin-top:0"><h2>${T[z.technique]}</h2><span class="badge ${z.parsed?'available':''}">${z.parsed?'parsed':'archived only'}</span></div>${z.parsed?plot(z.parsed,z.technique,z.metadata):`<div class="banner warning">${esc(z.parse_error)}</div>`}<p class="small"><a href="/api/files/${z.id}" download>${esc(z.filename)} · Download original</a></p><p class="small muted">${z.bytes.toLocaleString()} bytes${z.parsed?' · '+z.parsed.points.length.toLocaleString()+' data points':''}</p><details><summary>Acquisition metadata & fingerprint</summary><dl class="metadata">${Object.entries(z.metadata).filter(([,v])=>v).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl><p class="hash">SHA-256: ${z.sha256}</p></details></section>`).join('')}</div><div id="match-results"></div>${s.kind==='reference'&&s.status==='pending'?`<section class="panel" style="margin-top:1.5rem"><h2>Reference review</h2><p class="small muted">Review original acquisition conditions, data quality, attribution and independent compound identification. A matching score or the selected catalog name alone is not identification evidence. Approval is a local reviewer assertion, not certification.</p><form id="review-form" class="stack">${textField('reviewer','Reviewer name / lab','',true)}<label>Independent identity evidence & quality checks<textarea name="evidence" required placeholder="e.g. authenticated standard + orthogonal analysis; cite report/DOI; describe spectral quality checks"></textarea></label><label><input type="checkbox" name="confirmed" required> I have checked the original data, identity evidence, acquisition metadata and reuse permission.</label><button class="primary">Approve as a searchable reference</button><p id="review-error" role="alert" style="color:var(--warn)"></p></form></section>`:''}`;
  if(s.kind==='reference'){const c=await api('/api/compounds/'+s.compound_id);const target=document.querySelector('#sample-compound');if(!target)return;target.innerHTML=`<button class="ghost" id="open-identity">${esc(c.name)} · ${esc(c.formula)}</button><div class="structure" id="sample-mol">Drawing structure…</div>${coverage(c.coverage.map(z=>z.technique))}`;document.querySelector('#open-identity').onclick=()=>showCompound(c.id);structure(c.smiles,document.querySelector('#sample-mol'));}
  else{document.querySelector('#compare').onclick=()=>showMatches(id);await showMatches(id)}
  if(document.querySelector('#review-form'))document.querySelector('#review-form').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('button');button.disabled=true;try{const f=new FormData(form);await api('/api/samples/'+id+'/approve',{reviewer:f.get('reviewer'),evidence:f.get('evidence'),confirmed:f.get('confirmed')==='on'});flash('Reference review recorded. Parseable spectra are now searchable.');render()}catch(e){document.querySelector('#review-error').textContent=e.message;button.disabled=false}};
}
async function showMatches(id){const target=document.querySelector('#match-results'),button=document.querySelector('#compare');button.disabled=true;target.innerHTML='<p class="loading">Comparing compatible reviewed spectra…</p>';try{const d=await api('/api/samples/'+id+'/matches',{});if(!target.isConnected)return;target.innerHTML=`<div class="section-head"><h2>Candidate references</h2><span class="muted small">${d.approvedSamples||0} reviewed samples · ${d.skipped||0} incompatible</span></div>${d.results.length?`<div class="banner warning">${esc(d.warning)}</div>${d.results.map((r,i)=>`<section class="result"><div class="sample-head"><div><span class="eyebrow">Candidate ${i+1} · ${r.matchedModalities} of ${r.queryModalities} uploaded techniques compared</span><h2 style="margin-top:.5rem"><button class="ghost candidate" data-compound="${r.compound.id}">${esc(r.compound.name)}</button></h2><p class="muted small">${esc(r.compound.formula)} · <a href="#sample/${r.referenceId}">Reference sample: ${esc(r.referenceLabel)}</a></p></div><div><div class="score">${r.mean.toFixed(3)}</div><span class="small muted">mean similarity, not confidence</span></div></div>${r.scores.map(z=>`<p class="small">${T[z.technique]}: ${z.similarity.toFixed(3)} similarity · ${(z.coverage*100).toFixed(1)}% x-range overlap</p>`).join('')}<p class="small muted">Available in this reference sample: ${r.referenceModalities.map(t=>T[t]).join(', ')}. Follow the reference link to inspect its NMR/UV and original files. Those measurements do not confirm your unknown.</p></section>`).join('')}`:`<div class="empty"><h2>No eligible experimental reference</h2><p>${esc(d.reason)}</p><p>Add independently identified reference spectra, or collect complementary instrumental evidence. No identity prediction has been made.</p><a class="button" href="#upload-reference">Add a reference</a></div>`}`;target.querySelectorAll('.candidate').forEach(b=>b.onclick=()=>showCompound(b.dataset.compound));}catch(e){target.innerHTML=`<div class="banner warning">${esc(e.message)}</div>`}finally{button.disabled=false}}
async function settings(){const s=await api('/api/settings');if(location.hash!=='#settings')return;app.innerHTML=`<span class="eyebrow">Persistent local storage</span><h1>Storage</h1><div class="split"><section class="panel"><h2>Research bank on this computer</h2><dl class="metadata"><dt>Database</dt><dd><code>${esc(s.database)}\\spectratrace.sqlite</code></dd><dt>Original files</dt><dd><code>${esc(s.originals)}</code></dd><dt>Backups</dt><dd><code>${esc(s.backupFolder)}</code></dd><dt>File limit</dt><dd>${s.maxFileMB} MB per technique, one file per technique per sample</dd><dt>AI services</dt><dd>Disabled. Local numerical matching requires no paid AI API.</dd><dt>Identity catalog</dt><dd>${statsData.uniqueIdentities} unique identities; 500 memberships per collection</dd></dl><div class="banner warning">Local-only, single-user pilot. No authentication, online submissions, cloud sync or automatic backups. Do not expose this server to the internet. Store backups on another protected drive for disaster recovery.</div><button id="backup" class="primary">Create full backup</button><div id="backup-result" role="status"></div><p class="small muted">Backup includes a consistent SQLite snapshot, original upload files, downloaded source archives/extracted files, stored provenance and restore instructions. It does not include application code. Copy the SpectraTrace folder too when moving to another computer.</p><a class="button ghost" href="/api/catalog" download>Download all 1,500 catalog entries (JSON)</a></section><section class="panel"><h2>Coverage is evidence, not catalog size</h2>${statsData.collections.map(c=>`<p class="small"><strong>${esc(c.name)}</strong><br>${c.identities} identities · ${c.covered} with reviewed, usable spectra</p>`).join('')}<h2>Matching policy</h2><p class="small muted">Pending submissions and unknown samples are excluded. Different acquisition conditions and insufficient shared ranges are skipped. Scores are unvalidated cosine similarities, not calibrated probabilities.</p><p class="small muted">Original files are immutable. Correct an erroneous submission by adding a new, clearly labeled sample; do not overwrite the original bytes.</p></section></div><section class="panel" style="margin-top:1.5rem"><h2>Catalog sources & selection</h2><p class="small muted">Imported ${esc(statsData.sources.fetchedAt?.slice(0,10))}. This is a transparent starter subset, not a diversity-optimized or spectrally complete library.</p>${(statsData.sources.sources||[]).map(s=>`<div class="sample"><h3>${esc(s.provider)} ${esc(s.version||'')}</h3><p class="small muted">${esc(s.selection)}${s.license?'<br>Usage: '+esc(s.license):''}</p><a href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer">Original dataset / query</a></div>`).join('')}<p class="small"><a href="https://www.npatlas.org/download" target="_blank" rel="noopener noreferrer">NPAtlas download & license</a> · <a href="https://chembl.gitbook.io/chembl-interface-documentation/frequently-asked-questions/general-questions" target="_blank" rel="noopener noreferrer">ChEMBL terms</a> · <a href="https://pubchem.ncbi.nlm.nih.gov/docs/data-sources" target="_blank" rel="noopener noreferrer">PubChem attribution & licenses</a> · <a href="https://www.rdkitjs.com/" target="_blank" rel="noopener noreferrer">Structures rendered locally using RDKit.js (BSD-3-Clause)</a></p></section>`;
  document.querySelector('#backup').onclick=async e=>{e.target.disabled=true;try{const b=await api('/api/backups',{});document.querySelector('#backup-result').innerHTML=`<p>Backup saved: <a href="${b.url}" download>${esc(b.name)} · Download backup</a></p>`;flash('Database snapshot and original files backed up.')}catch(err){flash(err.message,true)}finally{e.target.disabled=false}};
}
window.addEventListener('hashchange',()=>{detail.close();render()});render();

function environmentTable(items,proton=false){const groups=new Map();for(const a of items){const key=a.environment+'|'+JSON.stringify(a.broadShiftPpm);if(!groups.has(key))groups.set(key,{environment:a.environment,range:a.broadShiftPpm,atoms:[],hydrogens:0});const g=groups.get(key);g.atoms.push(a.atomIndex);g.hydrogens+=a.count||0;}return `<div class="table-wrap"><table><thead><tr><th>Structural environment</th><th>Atom sites${proton?' / H count':''}</th><th>Broad guide (ppm)</th></tr></thead><tbody>${[...groups.values()].map(g=>`<tr><td>${esc(g.environment)}</td><td>${g.atoms.length} sites${proton?' / '+g.hydrogens+' H':''}<small>Indices (zero-based): ${g.atoms.join(', ')}</small></td><td>${g.range?g.range.join('–'):'Not assigned'}</td></tr>`).join('')}</tbody></table></div>`;}
function logicPanel(p){if(p.status==='unresolved-structure')return `<section class="panel"><h2>Structure logic unresolved</h2><p>${esc(p.error)}</p></section>`;return `<section class="panel logic-guide"><span class="eyebrow">Rule-derived · educational only · not experimental</span><h2>Structural spectroscopy guide</h2><div class="banner warning">Rule-derived, not measured spectra. Not used for unknown matching.</div><p class="small">${p.structure.carbonAtoms} carbon atoms · ${p.structure.carbonBoundHydrogens} carbon-bound H · ${p.structure.exchangeSensitiveHydrogens} exchange-sensitive H · ${p.structure.aromaticRings} aromatic rings. These are atom counts, not NMR resonance counts.</p><h3>Detected structural motifs</h3><div class="coverage">${p.functionalGroups.map(g=>`<span class="badge pending">${esc(g.label)}: ${g.siteCount} ${g.id==='aromatic'?'atoms':'sites'}</span>`).join('')||'No motif covered by the current rules'}</div><h3>FTIR screening regions</h3><div class="table-wrap"><table><thead><tr><th>Structure-derived feature</th><th>Broad region (cm⁻¹)</th><th>Limitations</th></tr></thead><tbody>${p.ftir.regions.map(r=>`<tr><td>${esc(r.label)}</td><td>${r.broadRegionCm1.join('–')}</td><td>${esc(r.note)}</td></tr>`).join('')||'<tr><td colspan="3">No supported screening region inferred.</td></tr>'}</tbody></table></div><details><summary>¹H NMR environment guide (not predicted peaks)</summary>${environmentTable(p.h1.atomEnvironments,true)}<p class="small muted">No splitting, coupling or equivalence assigned. Exchange-sensitive protons have no numerical region assigned.</p></details><details><summary>¹³C NMR environment guide (not predicted signals)</summary>${environmentTable(p.c13.atomEnvironments)}<p class="small muted">Symmetry and overlap are not resolved. This table is not a count of observed ¹³C resonances.</p></details><h3>UV–Vis structural hints</h3><p class="small">${p.uv.features.map(esc).join(' · ')||'No UV chromophore covered by the current rules was detected.'}</p><p class="small muted">${esc(p.uv.interpretation)} Exact λmax, absorbance and a full spectrum are not generated.</p><details><summary>Method, caveats & reproducibility</summary><p class="small">${esc(p.version)} · built ${esc(p.builtAt||'from source structure')} · <a href="#logic">Rules & source teaching links</a></p>${p.warnings.map(w=>`<p class="small muted">${esc(w)}</p>`).join('')}<p class="hash">Source SMILES SHA-256: ${esc(p.inputSha256)}</p></details></section>`;}
async function logicPage(){const d=await api('/api/logic-info');if(location.hash!=='#logic')return;app.innerHTML=`<div class="section-head"><div><span class="eyebrow">Educational · rule-derived</span><h1>Structure guides</h1></div><a class="button primary" href="/api/logic-dataset" download>Download dataset</a></div><div class="banner warning">Not experimental spectra or validated predictions. Unknown matching uses reviewed references only.</div><div class="grid"><section class="card"><h2>Collection entries</h2><div class="big">${d.counts.memberships.toLocaleString()}</div><p class="muted small">500 per collection</p></section><section class="card"><h2>Unique structures</h2><div class="big">${d.counts.identities.toLocaleString()}</div><p class="muted small">FTIR · ¹H / ¹³C NMR · UV hints</p></section><section class="card"><h2>Linked source evidence</h2><div class="big">${statsData.external.linkedIdentities}</div><p class="muted small">Separate imports · awaiting review</p></section></div><section class="panel" style="margin-top:1.3rem"><h2>From structure to spectral features</h2><p class="muted small">Open a compound to explore its functional groups, broad spectral regions and available evidence.</p><a class="button" href="#library">Browse compounds & guides</a></section><details class="disclosure"><summary>What these guides can and cannot tell you</summary><p class="small muted">Broad regions are chemical heuristics, not uncertainty intervals. No exact peaks, intensities, splitting, full curves or UV λmax are generated. These guides cannot uniquely identify an unknown from FTIR.</p><p class="small muted">Solvent, phase, hydrogen bonding, ionization, tautomers and stereochemistry affect real measurements. Missing measured spectra remain missing.</p><p class="small muted">The download contains unique structures, all 1,500 memberships, provenance, rules and public evidence links. Source licenses apply; researcher uploads are not exported.</p></details><details class="disclosure"><summary>Structural rules & scientific references</summary><p class="small muted">Method: ${esc(d.method)} · SMARTS graph motifs, not a learned prediction model.</p><div class="table-wrap"><table><thead><tr><th>Feature</th><th>SMARTS definition</th></tr></thead><tbody>${d.rules.map(r=>`<tr><td>${esc(r.label)}</td><td><code>${esc(r.smarts)}</code></td></tr>`).join('')}</tbody></table></div>${d.sources.map(s=>`<p class="small"><a href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a></p>`).join('')}<p class="small muted">References explain the principles. No source text, diagrams or spectral traces were copied into these guides.</p></details>`;}

function externalSummary(){const e=statsData.external||{total:0,groups:[],linkedIdentities:0};const curves=(e.uniqueCurves||[]).reduce((n,g)=>n+g.n,0);return `<section class="panel" style="margin-top:1.5rem"><span class="eyebrow">Public experimental sources · originals retained</span><h2>Imported evidence library</h2><div class="big">${e.total.toLocaleString()}<span class="small muted"> evidence records</span></div><p class="muted">${curves.toLocaleString()} distinct numerical curves (exact duplicates excluded) · ${e.linkedIdentities} starter-catalog identities linked by exact InChIKey. Other source structures remain searchable separately.</p><p class="small muted">NMR assignments, peak positions and literature band lists are counted separately from curves. Imports await independent review and are excluded from unknown matching. No predicted curves were imported.</p><a class="button primary" href="#evidence">Explore imported spectra & source data</a></section>`;}
let evidenceFilters={q:'',source:'',technique:'',representation:'',linked:'',offset:0};
const representations={'continuous':'Experimental IR curve','continuous-normalized':'Experimental UV curve (normalized)','peak-table':'IR peak table','assigned-shifts':'NMR assigned shifts','peak-positions':'NMR peak positions','reported-bands':'Literature IR bands','reported-text':'Literature NMR text','unparsed-jcamp':'Unparsed JCAMP archive'};
async function evidenceLibrary(){const e=statsData.external;app.innerHTML=`<span class="eyebrow">Source-backed imports</span><h1>Spectral evidence</h1><div class="banner warning">Imported, not independently reviewed. Excluded from unknown matching. NMR FIDs are not included.</div><div class="grid source-grid" style="margin-top:1rem">${e.sources.map(s=>{const groups=e.groups.filter(g=>g.source_id===s.id);return `<section class="card"><h2 title="${esc(s.title)}">${esc(({chemotion:'Chemotion','uv-advisor':'UV-adVISor',npmrd:'NP-MRD',irexp:'IRexp'})[s.id]||s.title)}</h2><div class="big">${groups.reduce((n,g)=>n+g.n,0).toLocaleString()}</div><details><summary>Data types & source details</summary><p class="small muted">${esc(s.license)}</p>${e.uniqueCurves?.find(c=>c.source_id===s.id)?`<p class="small"><strong>${e.uniqueCurves.find(c=>c.source_id===s.id).n.toLocaleString()} distinct numerical curves</strong> · ${e.uniqueCurves.find(c=>c.source_id===s.id).duplicates} duplicate curve records retained</p>`:''}<p class="small">${groups.map(g=>`${T[g.technique]} · ${esc(representations[g.representation]||g.representation)}: ${g.n.toLocaleString()} ${g.status==='quarantined'?'(quarantined)':''}`).join('<br>')}</p><a href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer">Original source & attribution</a><details><summary>Dataset provenance</summary><p class="small muted">${esc(s.metadata.notes)}</p>${s.metadata.archives.map(a=>`<p class="small">${esc(a.filename)} · ${Number(a.bytes).toLocaleString()} bytes<br>Retrieved ${esc(a.retrievedAt)}<br><span class="hash">SHA-256: ${esc(a.sha256)}</span></p>`).join('')}</details></details></section>`}).join('')}</div><section class="panel" style="margin-top:1.2rem"><form id="evidence-filters" class="fields"><label>Search name, InChIKey or source ID<input name="q" value="${esc(evidenceFilters.q)}" placeholder="e.g. aspirin, NP0000001"></label><label>Source<select name="source"><option value="">All sources</option>${e.sources.map(s=>`<option value="${s.id}" ${evidenceFilters.source===s.id?'selected':''}>${esc(s.title)}</option>`).join('')}</select></label><label>Technique<select name="technique"><option value="">All techniques</option>${Object.entries(T).map(([k,v])=>`<option value="${k}" ${evidenceFilters.technique===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Representation<select name="representation"><option value="">All data types</option>${Object.entries(representations).map(([k,v])=>`<option value="${k}" ${evidenceFilters.representation===k?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label>Catalog link<select name="linked"><option value="">Entire imported pool</option><option value="1" ${evidenceFilters.linked==='1'?'selected':''}>Linked to starter catalog only</option></select></label><button class="primary">Search imports</button></form></section><div id="evidence-results"></div>`;document.querySelector('#evidence-filters').onsubmit=e=>{e.preventDefault();evidenceFilters={...Object.fromEntries(new FormData(e.target)),offset:0};loadEvidence()};await loadEvidence();}
async function loadEvidence(){const holder=document.querySelector('#evidence-results');try{const d=await api('/api/evidence?'+new URLSearchParams(evidenceFilters));if(!holder.isConnected)return;holder.innerHTML=`<p class="small muted">${d.total.toLocaleString()} evidence records · separate experiments</p><div class="table-wrap"><table><thead><tr><th>Compound / source identity</th><th>Technique & data type</th><th>Source / status</th></tr></thead><tbody>${d.rows.map(e=>`<tr><td><a href="#evidence/${e.id}">${esc(e.name)}</a><small class="hash">${esc(e.inchikey||e.source_record)}</small>${e.compound_id?'<small>Exact starter-catalog identity link</small>':'<small>External identity; not one of the 500-per-collection seed</small>'}</td><td>${T[e.technique]}<small>${esc(representations[e.representation])}</small></td><td>${esc(e.source_id)}<small><span class="badge pending">${e.status==='quarantined'?'quarantined · inspect flags':'imported · needs review'}</span></small></td></tr>`).join('')}</tbody></table></div><div class="pager"><button id="evidence-prev" ${d.offset===0?'disabled':''}>Previous</button><span class="small muted">${d.total?d.offset+1:0}–${d.offset+d.rows.length} / ${d.total}</span><button id="evidence-next" ${d.offset+30>=d.total?'disabled':''}>Next</button></div>`;holder.querySelector('#evidence-prev').onclick=()=>{evidenceFilters.offset=Math.max(0,evidenceFilters.offset-30);loadEvidence()};holder.querySelector('#evidence-next').onclick=()=>{evidenceFilters.offset+=30;loadEvidence()};}catch(e){holder.textContent=e.message}}
async function evidenceView(id){const e=await api('/api/evidence/'+id);if(location.hash!=='#evidence/'+id)return;let view;if(e.parsed)view=plot(e.parsed,e.technique,e.metadata);else if(Array.isArray(e.data)&&['assigned-shifts','peak-positions'].includes(e.representation))view=`<div class="table-wrap"><table><thead><tr><th>Shift (ppm)</th><th>Atom</th><th>Multiplicity</th><th>Coupling (as reported)</th></tr></thead><tbody>${e.data.map(p=>`<tr><td>${esc(p.shift??p.shiftText??'unassigned')}</td><td>${esc(p.atom||'—')}</td><td>${esc(p.multiplicity||'—')}</td><td>${esc(p.couplingText||'—')}</td></tr>`).join('')}</tbody></table></div><p class="small muted">No intensities supplied. This is a chemical-shift table, not a reconstructed spectrum or raw FID.</p>`;else if(e.representation==='reported-bands')view=`<p>${e.data.map(v=>esc(v)+' cm⁻¹').join(' · ')}</p><p class="small muted">Reported band positions only; intensities, baseline and full trace are not supplied.</p>`;else view=`<p style="white-space:pre-wrap">${esc(typeof e.data==='string'?e.data:e.metadata.parseError||'Original archived; numerical interpretation unavailable.')}</p>`;
app.innerHTML=`<div class="section-head"><div><span class="eyebrow">${esc(e.source_title)}</span><h1>${esc(e.name)}</h1><span class="badge pending">${e.status==='quarantined'?'Quarantined · inspect metadata flags':'Imported · independent review needed'}</span></div><a class="button ghost" href="#evidence">All imports</a></div><div class="split"><section class="panel"><h2>${T[e.technique]} · ${esc(representations[e.representation])}</h2>${view}<div class="banner warning">Excluded from unknown matching. Check original compound assignment, acquisition conditions and reuse terms before using this as reference evidence.</div></section><section class="panel"><div id="evidence-mol" class="structure">${e.smiles?'Drawing source molecular structure…':'No resolved molecular structure in downloaded metadata.'}</div><p class="hash">${esc(e.inchikey||'No exact structure identifier available')}</p><p class="small">${e.compound_id?`<button class="link" id="evidence-compound">Open linked starter-catalog compound</button>`:'Identity retained in the external source pool; starter collections remain 500 each.'}</p><p class="small"><a href="${safeUrl(e.source_url)}" target="_blank" rel="noopener noreferrer">Original compound / publication source</a> · <a href="${safeUrl(e.dataset_url)}" target="_blank" rel="noopener noreferrer">Dataset source</a></p><p class="small">Reuse: ${esc(e.metadata.license||e.source_license)}</p><a class="button" href="/api/evidence/${e.id}/original" download>Download original source file</a><p class="small muted">Bulk CSV/JSONL downloads contain other records too; source record / row index below identifies this entry. File hashes refer to the original complete file.</p><p class="hash">SHA-256: ${esc(e.sha256)}</p></section></div><section class="panel" style="margin-top:1.3rem"><h2>Acquisition, extraction & identity metadata</h2><dl class="metadata"><dt>Source record</dt><dd>${esc(e.source_record)}</dd>${Object.entries(e.metadata).map(([k,v])=>`<dt>${esc(k)}</dt><dd style="white-space:pre-wrap">${esc(typeof v==='object'?JSON.stringify(v,null,2):v)}</dd>`).join('')}</dl></section>`;app.insertAdjacentHTML('beforeend',`<section class="panel" style="margin-top:1.3rem"><h2>Other evidence for this exact structure</h2><p class="small muted">These records share an InChIKey but may be separate samples, laboratories and conditions. They do not jointly confirm your unknown.</p>${e.related.length?e.related.map(r=>`<p><a href="#evidence/${r.id}">${T[r.technique]} · ${esc(representations[r.representation])} · ${esc(r.source_id)}</a> <span class="badge pending">${esc(r.status)}</span></p>`).join(''):'<p class="muted">No other downloaded evidence linked to this exact structure.</p>'}</section>`);if(e.smiles)structure(e.smiles,document.querySelector('#evidence-mol'));if(e.compound_id)document.querySelector('#evidence-compound').onclick=()=>showCompound(e.compound_id);}
function disclose(nodes,title){if(!nodes.length)return;const box=document.createElement('details');box.className='disclosure';const summary=document.createElement('summary');summary.textContent=title;box.append(summary);nodes[0].before(box);for(const node of nodes)box.append(node);return box}
function compactPage(hash){if(hash.startsWith('upload-')){app.classList.add('upload-shell');const aside=app.querySelector('aside');if(aside)disclose([aside],'File handling & limitations');if(hash==='upload-unknown'){const fields=app.querySelector('#upload-form .fields'),extra=[...fields.children].slice(1);if(extra.length){const box=disclose(extra,'Sample details (optional)');box.classList.add('span');const holder=document.createElement('div');holder.className='fields';for(const node of extra)holder.append(node);box.append(holder);}}}if(hash==='settings'){const sections=[...app.children].filter(n=>n.matches('section.panel'));if(sections.length)disclose([sections[sections.length-1]],'Catalog sources & selection');}if(hash==='samples'){const note=app.querySelector(':scope > p');if(note)disclose([note],'Review policy');}}
function compactCompound(){const holder=document.querySelector('#detail-body'),heads=[...holder.children].filter(n=>n.tagName==='H2');for(const head of heads){if(!['Identity provenance','Experimental submissions','Imported external evidence'].includes(head.textContent))continue;const nodes=[head];let node=head.nextElementSibling;while(node&&node.tagName!=='H2'&&node.id!=='contribute'&&!node.classList.contains('logic-guide')){nodes.push(node);node=node.nextElementSibling}const title=head.textContent;disclose(nodes,title);head.remove();}}
document.addEventListener('click',e=>{const more=document.querySelector('.nav-more');if(more&&!more.contains(e.target))more.open=false});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('.nav-more').open=false});
